memberdef.initializer:
do {                                                                         \
  if (Keyword == STR) {                                                      \
    TyVal = LLVMTY;                                                          \
    return lltok::Type;                                                      \
  }                                                                          \
} while (false)

do {                                                                         \
  if (Keyword == #STR) {                                                     \
    UIntVal = Instruction::Enum;                                             \
    return lltok::kw_##STR;                                                  \
  }                                                                          \
} while (false)

do {                                                                         \
  if (Keyword.starts_with("DW_" #TYPE "_")) {                                \
    StrVal.assign(Keyword.begin(), Keyword.end());                           \
    return lltok::TOKEN;                                                     \
  }                                                                          \
} while (false)

do {                                                                         \
  if (Keyword == "dbg_" #STR) {                                              \
    StrVal = #STR;                                                           \
    return lltok::DbgRecordType;                                             \
  }                                                                          \
} while (false)
